"python3 -c '
import re

with open("reports/IPSW_EXTRACTION_LEDGER.md", "r") as f:
    lines = f.readlines()

current_heading = "Header"
table_rows_by_heading = {}

for line in lines:
    if line.startswith("#"):
        current_heading = line.strip()
    elif line.startswith("|") and "`" in line:
        # Check if it has a file path pattern
        m = re.search(r"\|\s*`([^`]+)`\s*\|\s*([0-9,]+)\s*\|.*?`([0-9a-f]{64})`\s*\|", line)
        if m:
            table_rows_by_heading.setdefault(current_heading, []).append((m.group(1), m.group(2), m.group(3)))

for h, rows in table_rows_by_heading.items():
    print(f"{h}: {len(rows)} entries")
