import os

for rd in ["extracted/ipsw/ramdisk_erase", "extracted/ipsw/ramdisk_update"]:
    files, dirs, links = 0, 0, 0
    total_bytes = 0
    for root, d_names, f_names in os.walk(rd, followlinks=False):
        dirs += len(d_names)
        for item in d_names + f_names:
            p = os.path.join(root, item)
            if os.path.islink(p):
                links += 1
            elif os.path.isfile(p):
                files += 1
                total_bytes += os.path.getsize(p)
    print(f"{rd}: files={files}, dirs={dirs}, links={links}, regular_bytes={total_bytes}")
